mapper.sql:
select 0 id, '默认流程' alarm_flow_name, #{tenantId} tenant_id, t.flow_name flow_name, ti.template_id template_id, ti.creator creator, ti.create_time create_time, null update_time, '' modifier, ti.app_ver_code app_ver_code, ti.industry_code industry_code, '0' config_type from vm_flow_template_industry ti left join vm_flow_template t on ti.template_id = t.template_id where ti.delete_flag = 0 and ti.status = 1
AND ti.app_ver_code = #{appVerCode}
AND ti.industry_code = #{industryCode}

mapper.select:
select * from
(

	()
	union

(SELECT

,'1' config_type
FROM
vm_alarm_flow_config

	delete_flag = 0

		AND id = #{id}


		AND tenant_id = #{tenantId}


		AND status = #{status}


		AND app_ver_code = #{appVerCode}


		AND industry_code = #{industryCode}

	${dataScope}
)
) e


		AND template_id like CONCAT('%', #{templateId},'%')


		AND flow_name like CONCAT('%', #{flowName},'%')


		AND (alarm_flow_name like CONCAT('%', #{alarmFlowName},'%')

			OR creator in

				#{userId}


		)


		AND DATE_FORMAT(create_time,'%Y-%m-%d') >= DATE_FORMAT(#{createTimeStart},'%Y-%m-%d')
		AND DATE_FORMAT(create_time,'%Y-%m-%d') <= DATE_FORMAT(#{createTimeEnd},'%Y-%m-%d')


		AND template_id in

			#{templateId}





		order by create_time asc


		order by create_time desc


		order by update_time asc


		order by update_time desc


		order by create_time desc

SELECT
t1.id,
t1.alarm_flow_name,
t1.tenant_id,
t1.flow_name,
t1.template_id,
t2.id,
t2.warning_source,
t2.alarm_type
FROM
vm_alarm_flow_config t1
LEFT JOIN vm_flow_template_alarm_type t2 ON t1.id = t2.alarm_flow_id

	t1.delete_flag = 0


		AND t1.tenant_id = #{tenantId}


		AND t1.status = #{status}


		AND t1.alarm_flow_name = #{alarmFlowName}


		AND t1.app_ver_code = #{appVerCode}


		AND t1.industry_code = #{industryCode}


		AND concat(t2.alarm_type, '-', t2.warning_source)

			#{item}

SELECT t1.id, t2.id AS alarmFlowId, t2.tenant_id AS tenantId, t2.template_id AS templateId, t1.link_id AS linkId, t1.link_name AS linkName, t1.role_id AS roleId, t1.user_type AS userType, t1.msg_notify_type AS msgNotifyType, t1.msg_notify_limit AS msgNotifyLimit, t1.msg_notify_company AS msgNotifyCompany, t1.leader_flag AS leaderFlag, t1.rollback_flag AS rollbackFlag, t1.attr_flag AS attrFlag, t1.time_limit AS timeLimit, t1.creator, t1.create_time AS createTime, t1.modifier, t1.update_time AS updateTime FROM vm_flow_link_industry_config t1 LEFT JOIN vm_alarm_flow_config t2 ON t1.industry_code = t2.industry_code WHERE t1.status = '1'
AND t2.id = #{alarmFlowId}
AND t1.app_ver_code is null AND industry_code is null
AND t1.industry_code = #{industryCode}
AND t1.app_ver_code = #{appVerCode}

SELECT t2.template_id AS templateId, t1.link_id AS linkId, t1.link_name AS linkName, t1.role_id AS roleId, t1.user_type AS userType, t1.msg_notify_type AS msgNotifyType, t1.msg_notify_limit AS msgNotifyLimit, t1.msg_notify_company AS msgNotifyCompany, t1.leader_flag AS leaderFlag, t1.rollback_flag AS rollbackFlag, t1.attr_flag AS attrFlag, t1.time_limit AS timeLimit, 0 as turnFlag, t1.grid_user_type, t1.data_filter_permiss, t1.custom_admin, t1.time_limit_company, t1.time_start_alram, t1.time_end_alram, t1.voice_alram, t1.time_remind, t1.time_remind_auto, t1.time_remind_number, t1.if_later_remind, t1.later_remind, t1.later_remind_company, t1.time_push_type, t1.time_limit_push, t1.msg_send_time_interval, 2 as gridUserType, t1.grid_sign_role FROM vm_flow_link_industry_config t1 LEFT JOIN vm_flow_template_industry t2 ON t1.industry_code = t2.industry_code and t1.app_ver_code = t2.app_ver_code WHERE t2.status = '1' and t1.delete_flag='0' and t2.delete_flag='0'
AND t1.industry_code = #{industryCode}
AND t1.app_ver_code = #{appVerCode}

select tenant_id as tenantId, tenant_name as tenantName
from sys_tenant_info where tenant_id in

	#{tenantId}

SELECT t.tenant_id, t.industry_code, '11' AS alarmSource, t.warning_source_name AS 'alarmSourceName', t.alarm_type AS 'typeValue' FROM vm_third_party_alarm t WHERE t.delete_flag = 0
AND t.tenant_id = #{tenantId}
AND t.industry_code = #{industryCode}

SELECT DISTINCT d.tenant_id AS tenantId, '0' AS dept, d.dept_id AS pid, d.dept_name AS deptName, d.industry_code as industryCode, u.user_id AS id, u.user_name AS userName, u.nick_name AS nickName, u.sex AS sex, u.avatar AS avatar FROM sys_dept d LEFT JOIN sys_user u on FIND_IN_SET( d.DEPT_ID, u.DEPT_ID ) AND u.DEL_FLAG = '0' WHERE d.del_flag = '0' AND d.tenant_id = #{tenantId} and d.INDUSTRY_CODE=#{industryCode}
AND u.nick_name like concat('%',#{nickName},'%')
AND u.USER_ID in
#{userId}

select count(1) from vm_alarm_flow_config
where alarm_flow_name = #{alarmFlowName}
and delete_flag = '0'
and tenant_id = #{tenantId}
and app_ver_code = #{appVerCode}
and industry_code = #{industryCode}

	and id != #{id}

