set delete_flag = 1
where tenant_id = #{tenantId}
and industry_code = #{industryCode,jdbcType=VARCHAR}
and app_ver_code = #{appVerCode,jdbcType=VARCHAR}

	AND concat(alarm_type, '-', warning_source)

		#{item}



	and alarm_flow_id != #{id}

and delete_flag= 0

