mapper.select:
select concat(alarm_type, '-', warning_source)
from vm_flow_template_alarm_type
where tenant_id = #{tenantId}
and industry_code = #{industryCode,jdbcType=VARCHAR}
and app_ver_code = #{appVerCode,jdbcType=VARCHAR}
and delete_flag= 0

	AND concat(alarm_type, '-', warning_source)

		#{item}

select distinct warning_source, alarm_type
from vm_flow_template_alarm_type
where tenant_id = #{tenantId}
  and industry_code = #{industryCode,jdbcType=VARCHAR}
  and app_ver_code = #{appVerCode,jdbcType=VARCHAR}
  and delete_flag= 0
order by warning_source

SELECT DISTINCT  c.id, c.alarm_flow_name alarmFlowName FROM
`vm_flow_link_role` r
left join vm_flow_link_attr a on  a.id = r.attr_id
left join vm_alarm_flow_config c on a.alarm_flow_id = c.id
where r.role_id = #{roleId}

	and r.tenant_id = #{tenantId}
	and c.tenant_id =  #{tenantId}


	and c.industry_code =  #{industryCode,jdbcType=VARCHAR}


	and c.app_ver_code =  #{appVerCode,jdbcType=VARCHAR}


	and c.delete_flag = #{deleteFlag}
	and r.delete_flag = #{deleteFlag}
	and a.delete_flag = #{deleteFlag}

SELECT DISTINCT  c.id, c.alarm_flow_name alarmFlowName FROM
`vm_flow_link_user` u
left join vm_flow_link_attr a on  a.id = u.attr_id
left join vm_alarm_flow_config c on a.alarm_flow_id = c.id
where u.user_id = #{userId}

	and u.tenant_id = #{tenantId}
	and c.tenant_id =  #{tenantId}


	and c.industry_code =  #{industryCode,jdbcType=VARCHAR}


	and c.app_ver_code =  #{appVerCode,jdbcType=VARCHAR}


	and c.delete_flag = #{deleteFlag}
	and u.delete_flag = #{deleteFlag}
	and a.delete_flag = #{deleteFlag}

SELECT DISTINCT '' as alarmFlowName, o.flow_id
FROM ${tableName} o
where o.order_status not in (0,6,7) AND o.delete_flag = '0'

	and (o.flow_id in

		#{item.id}


		or FIND_IN_SET(#{userId}, o.process_id)

	)


	and o.flow_template = CONCAT('',#{templateId},'')



		and FIND_IN_SET(#{userId}, o.process_id)



	and o.industry_code = #{industryCode}


	and o.tenant_id = #{tenantId}
